return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-09-08T20:38:01+00:00','po-revision-date'=>'2026-09-08T20:38:01+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — footprint-free PBN, WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'Prodajte Zinn Digital® hosting sa svoje vlastite WordPress stranice – PBN bez tragova, WordPress, WooCommerce, agencijski, reseller, cloud i VPS hosting. Pretražujte i nudite domene sa svog reseller računa, prijavite svoje klijente izravno u njihovu hosting ploču i automatski osigurajte hosting kada je WooCommerce narudžba plaćena.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'Platforma za hosting odgovorila je sa statusom %d.','Find your domain name'=>'Pronađite naziv svoje domene','Search'=>'Pretraži','No extensions were checked for that name.'=>'Za taj naziv nije označena nijedna ekstenzija.','Domain search is unavailable on this site at the moment.'=>'Pretraživanje domena trenutno nije dostupno na ovoj stranici.','We could not reach the domain registry just now. Please try again in a moment.'=>'Trenutno nismo mogli uspostaviti vezu s registrom domena. Molimo pokušajte ponovno za trenutak.','The API key is missing or no longer valid. Check it under Settings → Zinn® Reseller.'=>'API ključ nedostaje ili više nije valjan. Provjerite ga u odjeljku Postavke → Zinn® Reseller.','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'Ovaj API ključ nema dozvolu sites.view koja je potrebna za pretraživanje domena. Dodajte je u ključ na svojoj resellerskoj ploči ili ovdje izbrišite ključ kako biste se vratili na javno pretraživanje.','Only administrators see this:'=>'Samo administratori ovo vide:','We could not check this one — try again'=>'Nismo mogli provjeriti ovu stavku — pokušajte ponovno','Already registered'=>'Već registrirano','Available — ask us for a price'=>'Dostupno — pitajte nas za cijenu','Available — %1$s %2$s for the first year'=>'Dostupno — %1$s %2$s za prvu godinu','Register it'=>'Registriraj ga','Manage my hosting'=>'Upravljanje mojim hostingom','Please sign in first.'=>'Molimo vas da se najprije prijavite.','This account is not linked to a hosting service yet.'=>'Ovaj račun još nije povezan s uslugom hostinga.','The hosting platform did not return a sign-in link.'=>'Platforma za hosting nije vratila vezu za prijavu.','Reseller Toolkit'=>'Alatni okvir za preprodavače','Account'=>'Korisnički račun','Features'=>'Značajke','Styling'=>'Stilski dizajn','Your Zinn Digital® reseller account'=>'Vaš resellerski račun za Zinn Digital®','Create a reseller API key in your Zinn® dashboard under Settings → API keys, and paste it here.'=>'Izradite API ključ preprodavača na svojoj Zinn® upravljačkoj ploči pod Postavke → API ključevi i zalijepite ga ovdje.','Reseller API key'=>'API ključ za preprodavače','Held on this site only, and never included in an export or a diagnostics report.'=>'Pohranjeno samo na ovoj web-lokaciji i nikada nije uključeno u izvoz ili izvješće o dijagnostici.','Plan to provision'=>'Plan za dodjelu resursa','The plan code new customers are put on. Leave blank to be asked each time.'=>'Kod plana na koji se stavljaju novi korisnici. Ostavite prazno da se pita svaki put.','API address'=>'API adresa','Leave this alone unless Zinn® support has asked you to change it.'=>'Ovo nemojte mijenjati osim ako vas podrška za Zinn® nije zatražila da to promijenite.','Control-panel address'=>'Adresa upravljačke ploče','Where the “My hosting” link sends your customers.'=>'Kamo poveznica „Moje udomljavanje” šalje vaše klijente.','Domain search'=>'Pretraga domena','Provide the [zinn_domain_search] shortcode'=>'Unesite kratki kôd [zinn_domain_search]','Put the shortcode on any page to let visitors check a domain and buy it through you.'=>'Postavite kratki kod na bilo koju stranicu kako biste omogućili posjetiteljima provjeru domene i kupnju putem vas.','Panel link'=>'Veza s upravljačkom pločom','Show a “My hosting” link to signed-in customers'=>'Prikaži vezu „Moje hosting usluge” prijavljenim korisnicima','WooCommerce provisioning'=>'Instalacija WooCommerce','Provision hosting automatically when a WooCommerce order completes'=>'Automatski kreirajte hosting kada se WooCommerce narudžba dovrši','Only takes effect on orders containing a product you have mapped to a Zinn® plan.'=>'Primjenjuje se samo na narudžbe koje sadrže proizvod koji ste povezali sa Zinn® paketom.','Domain search appearance'=>'Izgled pretraživanja domene','This widget renders inside your own theme. Pick a preset, or set your own colours — either way nothing is added to your pages that a visitor can see as ours.'=>'Ovaj se widget prikazuje unutar vaše vlastite teme. Odaberite predložak ili postavite vlastite boje — u svakom slučaju, vašim se stranicama ne dodaje ništa što posjetitelj može vidjeti kao naše.','Every class the widget uses is listed in the plugin’s readme, so a developer can override anything a preset does not cover.'=>'Svaka klasa koju widget koristi navedena je u datoteci readme dodatka, tako da programer može nadjačati sve što unaprijed postavljena postavka ne obuhvaća.','Follow my theme'=>'Slijedi moju temu','Soft'=>'Meko','High contrast'=>'Visoki kontrast','Compact'=>'Kompaktno','Buy-link colour'=>'Boja veze za kupnju','“Available” colour'=>'Boja za „Dostupno”','“Could not check” colour'=>'Boja za „Nije moguće provjeriti”','Error colour'=>'Boja pogreške','Corner rounding'=>'Zaobljenje kutova','Space inside each row'=>'Prostor unutar svakog retka','Text size'=>'Veličina teksta','Domain-name weight'=>'Težina naziva domene','No reseller API key yet.'=>'Još nema API ključa za preprodavače.','Nothing here works until a key is set. Create one in your Zinn® dashboard under Settings → API keys.'=>'Ništa ovdje ne radi dok se ne postavi ključ. Izradite ga u svojoj Zinn® upravljačkoj ploči pod Postavke → API ključevi.','Open my Zinn® dashboard'=>'Otvorite moju Zinn® upravljačku ploču','A key is set, but nothing is switched on.'=>'Ključ je postavljen, ali ništa nije uključeno.','None of the three features is enabled, so this plugin is doing nothing on your site. Turn on what you need under Features.'=>'Nijedna od tri značajke nije omogućena, tako da ovaj dodatak ne radi ništa na vašoj stranici. Uključite ono što vam treba pod Značajke.','Open Features'=>'Otvori značajke','Ready — %d feature switched on.'=>'Spremno — %d značajka uključena.' . "\0" . 'Spremno — %d značajki je uključeno.' . "\0" . 'Spremno — %d značajki je uključeno.','Selling from'=>'Prodaje od','Settings'=>'Postavke','No API key yet, so nothing is connected.'=>'Još nema API ključa, pa ništa nije povezano.','Not connected: %s'=>'Nije povezano: %s','Connected. Your reseller programme is %s.'=>'Povezano. Vaš resellerski program je %s.','No Zinn® API key is configured, so nothing was provisioned.'=>'Nije konfiguriran nikakav Zinn® API ključ, tako da ništa nije dodijeljeno.','This order did not include a domain name, so there was nothing to provision.'=>'Ova narudžba nije uključivala naziv domene, tako da nije bilo ničega za rezervirati.','The hosting platform did not return a site.'=>'Platforma za hosting nije vrati